body {
  font-family: system-ui, sans-serif;
  margin: 0;
  background: #f5f5f5;
}
header {
  background: #222;
  color: white;
  padding: 1rem;
  text-align: center;
}
#board {
  display: flex;
  gap: 1rem;
  padding: 1rem;
  overflow-x: auto;
  min-height: 80vh;
}
.column {
  background: #e2e8f0;
  border-radius: 8px;
  width: 280px;
  display: flex;
  flex-direction: column;
  padding: 0.5rem;
}
.column h2 {
  margin: 0 0 0.5rem;
  font-size: 1.1rem;
}
.cards {
  flex: 1;
  min-height: 50px;
}
.card {
  background: white;
  border-radius: 6px;
  padding: 0.5rem;
  margin-bottom: 0.5rem;
  cursor: grab;
  box-shadow: 0 1px 2px rgba(0,0,0,0.1);
}
.card.dragging {
  opacity: 0.5;
}
.add-card {
  display: flex;
  gap: 0.25rem;
  margin-top: 0.5rem;
}
.add-card input {
  flex: 1;
  padding: 0.4rem;
  border: 1px solid #ccc;
  border-radius: 4px;
}
.add-card button {
  padding: 0.4rem 0.6rem;
  border: none;
  background: #4a90e2;
  color: white;
  border-radius: 4px;
  cursor: pointer;
}
.column-placeholder {
  border: 2px dashed #bbb;
  margin: 0.5rem 0;
}

