    const { columnId, cards } = JSON.parse(e.data);
    const col = boardState.find(c => c.id === columnId);
    if (col) {
      col.cards = cards;
      renderBoard();
    }
  });
  eventSource.onerror = () => {
    console.warn('SSE error, retrying...');
    eventSource.close();
    setTimeout(connectSSE, 3000);
  };
}

