    cardsContainer.addEventListener('dragover', e => {
      e.preventDefault();
      const afterElement = getDragAfterElement(cardsContainer, e.clientY);
      const draggable = document.querySelector('.dragging');
      if (draggable) {
        if (afterElement == null) {
          cardsContainer.appendChild(draggable);
        } else {
          cardsContainer.insertBefore(draggable, afterElement);
        }
      }
    });
    cardsContainer.addEventListener('drop', e => {
      e.preventDefault();
      const cardId = e.dataTransfer.getData('text/plain');
      const cardEl = document.getElementById(`card-${cardId}`);
      if (!cardEl) return;
      const afterElement = getDragAfterElement(cardsContainer, e.clientY);
      if (afterElement == null) {
        cardsContainer.appendChild(cardEl);
      } else {
        cardsContainer.insertBefore(cardEl, afterElement);
      }
      const beforeId = afterElement ? afterElement.dataset.cardId : null;
      const afterId = beforeId ? getPrevCardId(afterElement) : getLastCardId(cardsContainer);
      // optimistic already done, now send
      moveCard(cardId, col.id, beforeId, afterId);
    });
    colEl.addEventListener('dragover', e => e.preventDefault());
    colEl.addEventListener('drop', e => {
      // drop on empty column
      const cardId = e.dataTransfer.getData('text/plain');
      const cardEl = document.getElementById(`card-${cardId}`);
      if (!cardEl) return;
      const cardsContainer = colEl.querySelector('.cards');
      cardsContainer.appendChild(cardEl);
      moveCard(cardId, col.id, null, getLastCardId(cardsContainer) === cardId ? null : getLastCardId(cardsContainer));
    });
    boardEl.appendChild(colEl);
  });
  setupDraggableCards();
}

function createCardElement(card) {
  const el = document.createElement('div');
  el.className = 'card';
  el.id = `card-${card.id}`;
  el.draggable = true;
  el.dataset.cardId = card.id;
  el.textContent = card.text;
  el.addEventListener('dragstart', e => {
    e.dataTransfer.setData('text/plain', card.id);
    setTimeout(() => el.classList.add('dragging'), 0);
  });
  el.addEventListener('dragend', () => el.classList.remove('dragging'));
  return el;
}

function setupDraggableCards() {
  document.querySelectorAll('.card').forEach(card => {
    if (!card.hasAttribute('data-drag-bound')) {
      card.setAttribute('data-drag-bound', '1');
      card.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', card.dataset.cardId);
        setTimeout(() => card.classList.add('dragging'), 0);
      });
      card.addEventListener('dragend', () => card.classList.remove('dragging'));
    }
  });
}

function getDragAfterElement(container, y) {
  const cards = [...container.querySelectorAll('.card:not(.dragging)')];
  return cards.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      return { offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

function getPrevCardId(element) {
  const prev = element.previousElementSibling;
  return prev ? prev.dataset.cardId : null;
}

function getLastCardId(container) {
  const cards = container.querySelectorAll('.card');
  if (!cards.length) return null;
  return cards[cards.length - 1].dataset.cardId;
}

async function addCard(columnId, inputEl) {
  const text = inputEl.value.trim();
