    const maxRes = await pg.exec(`SELECT MAX(position) AS maxPos FROM cards WHERE column_id = $1 ${excludeCardId ? 'AND id <> $2' : ''}`, excludeCardId ? [columnId, excludeCardId] : [columnId]);
